package com.citacloud.springboot.contacloud.app.services;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;import java.util.UUID;@Service public class AjusteInventarioNumeroService{private final JdbcTemplate jdbc;public AjusteInventarioNumeroService(JdbcTemplate j){jdbc=j;}public String siguiente(UUID t,UUID e){Long n=jdbc.queryForObject("INSERT INTO inventory_adjustment_sequence(tenant_id,empresa_id,last_number) VALUES(?,?,1) ON CONFLICT(tenant_id,empresa_id) DO UPDATE SET last_number=inventory_adjustment_sequence.last_number+1 RETURNING last_number",Long.class,t,e);return "AJU-"+String.format("%06d",n);}}
